 const patchListing=async(item:Listing,patch:Partial<Listing>,summary:string)=>{setItems(prev=>prev.map(x=>x.id===item.id?{...x,...patch}:x));if(supabaseReady&&session){const db:any={};if(patch.status)db.status=patch.status;if(patch.ngoId!==undefined)db.recipient_id=patch.ngoId;if(patch.riderId!==undefined)db.rider_id=patch.riderId;if(patch.photo!==undefined)db.donor_photo=patch.photo;if(patch.pickupPhoto!==undefined)db.pickup_photo=patch.pickupPhoto;if(patch.dropPhoto!==undefined)db.dropoff_photo=patch.dropPhoto;if(patch.receivedPhoto!==undefined)db.ngo_received_photo=patch.receivedPhoto;if(patch.rejectReason!==undefined)db.reject_reason=patch.rejectReason;const{error}=await supabase.from('food_listings').update(db).eq('id',item.id);if(error)Alert.alert('Could not save update',error.message)}void summary;};
 const capture=async(item:Listing,type:'photo'|'pickupPhoto'|'dropPhoto'|'receivedPhoto',uri:string):Promise<boolean>=>{if(supabaseReady&&session){const path=session.user.id+'/'+item.id+'/'+type+'-'+Date.now()+'.jpg';try{const blob=await(await fetch(uri)).blob();const bytes=await blob.arrayBuffer();const hashBuffer=await Crypto.digest(Crypto.CryptoDigestAlgorithm.SHA256,bytes);const sha256=Array.from(new Uint8Array(hashBuffer)).map(value=>value.toString(16).padStart(2,'0')).join('');const{error}=await supabase.storage.from('food-evidence').upload(path,blob,{contentType:'image/jpeg'});if(error)throw error;let latitude:number|null=null,longitude:number|null=null;try{const permission=await Location.requestForegroundPermissionsAsync();if(permission.granted){const position=await Location.getCurrentPositionAsync({accuracy:Location.Accuracy.Balanced});latitude=position.coords.latitude;longitude=position.coords.longitude}}catch{}const expectedAddress=type==='photo'||type==='pickupPhoto'?item.address:item.ngoAddress;let expectedLatitude:number|null=null,expectedLongitude:number|null=null;if(expectedAddress){try{const point=await Location.geocodeAsync(expectedAddress);if(point[0]){expectedLatitude=point[0].latitude;expectedLongitude=point[0].longitude}}catch{}}const step=type==='photo'?'donor-packed':type==='pickupPhoto'?'rider-pickup':type==='dropPhoto'?'rider-dropoff':'ngo-inspection';const{error:captureError}=await supabase.from('food_listing_captures').insert({listing_id:item.id,step,actor_id:session.user.id,storage_path:path,sha256,latitude,longitude,expected_latitude:expectedLatitude,expected_longitude:expectedLongitude});if(captureError)throw captureError;uri=path}catch(e){Alert.alert('Photo evidence not saved',e instanceof Error?e.message:'Try again');return false}}await patchListing(item,{[type]:uri} as Partial<Listing>,type+' evidence captured');return true};
