  if(act==='pickup'){const photo=cameraTarget.startsWith(item.id+'|')?cameraTarget.slice(item.id.length+1):'';if(!photo)return Alert.alert('Photo required','Capture the food before confirming pickup.');if(!await capture(item,'pickupPhoto',photo))return;setCameraTarget('');await patchListing(item,{status:'Picked up'},'Pickup confirmed');return}
