 if(supabaseReady&&session&&profile?.approval_status&&profile.approval_status!=='approved')return <SafeAreaView style={s.safe}><View style={[s.loading,{padding:28}]}><BrandMark/><Text style={[s.heading,{textAlign:'center',marginTop:22}]}>{profile.approval_status==='rejected'?'Account not approved':'Account awaiting review'}</Text><Text style={[s.muted,{textAlign:'center',marginTop:10}]}>{profile.approval_note||'An administrator needs to verify this account before you can access the operational workspace.'}</Text><Btn label="Sign out" onPress={()=>void supabase.auth.signOut()} subtle/></View></SafeAreaView>;
 if(!role)return <RolePicker onPick={chooseRole} t={t}/>;
  const roleName=role==='ngo'?'NGO team':role==='rider'?'Delivery partner':role==='admin'?'Administrator':'Food donor';
 const homeData=role==='donor'?items.filter(x=>!supabaseReady||x.donorId===ownId):role==='ngo'?items.filter(x=>(x.status==='Awaiting NGO'&&!x.declines.includes(profile?.id||profile?.display_name||''))||x.ngoId===ownId||x.ngo===profile?.display_name||!supabaseReady):items.filter(x=>x.status==='Rider needed'||x.riderId===ownId||(!supabaseReady&&['Rider assigned','Picked up','In transit','Almost complete'].includes(x.status))||x.rider==='Maya S.'||x.rider==='Arjun K.');
 const reviewData=items.filter(i=>i.status==='Delivered'&&(!supabaseReady||i.ngoId===ownId)&&!i.review);
 const navItems=role==='donor'?[{key:'home',label:'Home',icon:House},{key:'archive',label:'Batches',icon:Archive},{key:'rewards',label:'Impact',icon:Star},{key:'profile',label:'Profile',icon:UserRound}]:role==='ngo'?[{key:'home',label:'Offers',icon:Package},{key:'archive',label:'Orders',icon:Archive},{key:'review',label:'Reviews',icon:CheckCircle2},{key:'profile',label:'Profile',icon:UserRound}]:[{key:'home',label:'Runs',icon:Truck},{key:'archive',label:'History',icon:Archive},{key:'safety',label:'Safety',icon:ShieldCheck},{key:'profile',label:'Profile',icon:UserRound}];
